#!/usr/bin/env python3
"""Generate a .clangd config with common flags extracted from compile_commands.json.

Scans compile_commands.json for flags, defines, include paths, and forced includes
that appear in the majority (>50%) of entries, then writes a .clangd file so that
header files get the same flags.

Also removes GCC-only flags that clang doesn't understand.

Usage:
    gen-clangd-config.py [path/to/compile_commands.json]

If no path is given, searches for compile_commands.json in common locations
(build/, src/build/, etc.) relative to the current directory.
"""

import json
import os
import sys
from collections import Counter
from pathlib import Path

# GCC-only flags that clang does not support
GCC_ONLY_FLAGS = [
    "-fno-var-tracking-assignments",
]


def find_compile_commands():
    """Search for compile_commands.json in common build directories."""
    candidates = [
        "compile_commands.json",
        "build/compile_commands.json",
        "src/build/compile_commands.json",
    ]
    for c in candidates:
        if os.path.isfile(c):
            return c
    return None


def extract_common_flags(entries, build_dir):
    """Extract flags, defines, include paths, and forced includes from compile commands."""
    total = len(entries)
    threshold = total / 2

    defines = Counter()
    forced_includes = Counter()
    include_dirs = Counter()
    interesting_flags = Counter()

    for entry in entries:
        parts = entry["command"].split()
        entry_dir = entry.get("directory", build_dir)
        i = 0
        while i < len(parts):
            p = parts[i]
            if p.startswith("-D"):
                defines[p] += 1
            elif p == "-include" and i + 1 < len(parts):
                forced_includes[parts[i + 1]] += 1
                i += 1
            elif p.startswith("-I"):
                inc_path = p[2:]
                # Resolve relative paths against the entry's directory
                if not os.path.isabs(inc_path):
                    inc_path = os.path.normpath(os.path.join(entry_dir, inc_path))
                include_dirs[inc_path] += 1
            elif p.startswith("--sysroot="):
                interesting_flags[p] += 1
            elif p.startswith("--target="):
                interesting_flags[p] += 1
            elif p.startswith("-march=") or p.startswith("-mcpu="):
                interesting_flags[p] += 1
            elif p.startswith("-std="):
                interesting_flags[p] += 1
            i += 1

    result = {"defines": [], "forced_includes": [], "flags": [], "include_dirs": [], "remove": list(GCC_ONLY_FLAGS)}

    for d, cnt in defines.most_common():
        if cnt > threshold:
            result["defines"].append(d)

    for inc, cnt in forced_includes.most_common():
        if cnt > threshold:
            result["forced_includes"].append(inc)

    for f, cnt in interesting_flags.most_common():
        if cnt > threshold:
            result["flags"].append(f)

    for d, cnt in include_dirs.most_common():
        if cnt > threshold:
            result["include_dirs"].append(d)

    return result


def write_clangd_config(flags, output_path):
    """Write a .clangd config file."""
    lines = ["# Auto-generated by gen-clangd-config.py", "# Provides fallback flags for header files", "CompileFlags:"]

    add_flags = []
    add_flags.extend(flags["flags"])
    add_flags.extend(flags["defines"])

    if flags["include_dirs"]:
        lines.append("  Add:")
        for f in add_flags:
            lines.append(f"    - {f}")
        lines.append("    # Include paths for standalone header analysis")
        for d in flags["include_dirs"]:
            lines.append(f"    - -I{d}")
        lines.append("    # Forced includes for type definitions")
        for inc in flags["forced_includes"]:
            lines.append("    - -include")
            lines.append(f"    - {inc}")
    else:
        lines.append("  Add:")
        for f in add_flags:
            lines.append(f"    - {f}")
        for inc in flags["forced_includes"]:
            lines.append("    - -include")
            lines.append(f"    - {inc}")

    if flags["remove"]:
        lines.append("  Remove:")
        for f in flags["remove"]:
            lines.append(f"    - {f}")

    content = "\n".join(lines) + "\n"

    with open(output_path, "w") as f:
        f.write(content)

    print(f"Wrote {output_path}")
    print(f"  {len(add_flags)} flags, {len(flags['include_dirs'])} include dirs, "
          f"{len(flags['forced_includes'])} forced includes, {len(flags['remove'])} removed flags")
    print()
    print(content)


def main():
    if len(sys.argv) > 1:
        cc_path = sys.argv[1]
    else:
        cc_path = find_compile_commands()

    if not cc_path or not os.path.isfile(cc_path):
        print("Error: compile_commands.json not found", file=sys.stderr)
        print("Usage: gen-clangd-config.py [path/to/compile_commands.json]", file=sys.stderr)
        sys.exit(1)

    cc_path = os.path.abspath(cc_path)
    build_dir = os.path.dirname(cc_path)

    with open(cc_path) as f:
        entries = json.load(f)

    print(f"Scanned {len(entries)} entries from {cc_path}")

    flags = extract_common_flags(entries, build_dir)

    # Write .clangd next to compile_commands.json's project root
    project_root = Path(cc_path).resolve().parent
    # If compile_commands.json is in a build/ subdir, go up
    if project_root.name in ("build", "Build", "BUILD"):
        project_root = project_root.parent

    output_path = project_root / ".clangd"
    write_clangd_config(flags, output_path)


if __name__ == "__main__":
    main()
